 p1=anchor(a,c1.x,c1.y);p2=anchor(b,c1.x,c1.y);mid={x:(p1.x+p2.x)/4+c1.x/2,y:(p1.y+p2.y)/4+c1.y/2};path=`M ${p1.x} ${p1.y} Q ${c1.x} ${c1.y} ${p2.x} ${p2.y}`}
